#!/usr/bin/env python3
"""Author's PR-body refresh for Math-#447 after the integrator's source-identical carry (head f6ba2e6a, base main).
Exact-string edits on the current body, every edit asserted; adds the hosted-runs bullet for the carried head from
lvs/r7/hosted_runs_line_f6ba2e6a.md (written by bind_text_pr.py after the runs completed); strips the proxy footers
before PATCH; prints the diff summary. No branch push. Scientific effect NONE."""
import json, re, subprocess, sys
from pathlib import Path
S = Path('<SCRATCH>')
REPO = 'd6g8k5htny-coder/Math-'; PR = 447
HEAD = 'f6ba2e6ab398b2c4081d0de2a551caea2e6d46ba'
import datetime as _dt
BOUND = _dt.datetime.now(_dt.timezone.utc).strftime('%H:%MZ')
def api(*args, inp=None):
    r = subprocess.run(['gh', 'api', *args], capture_output=True, text=True, input=inp); assert r.returncode == 0, (args, r.stderr[:400]); return r.stdout
p = json.loads(api(f'repos/{REPO}/pulls/{PR}'))
assert p['head']['sha'] == HEAD and p['base']['ref'] == 'main' and not p['merged'], (p['head']['sha'], p['base']['ref'], p['merged'])
body = p['body']
line = (S / 'lvs/r7/hosted_runs_line_f6ba2e6a.md').read_text().strip()
assert line.startswith('the three pull_request runs on PR head `f6ba2e6a`'), line[:80]
FOOT = re.compile(r'(\n\n---\n_Generated by \[Claude Code\]\(https://claude\.ai/code[^)]*\)_)+\Z')
body = FOOT.sub('', body)
def rep(old, new):
    global body
    assert body.count(old) == 1, (body.count(old), old[:80]); body = body.replace(old, new)
rep("**Draft. Stacked on #445 (base branch `claude/lean-statements-frontier-20261013`; base head now `0c506fea` after #445's amendments 445-A to 445-D, merged into this PR as `06f03d06` with the documents regenerated by the same binder; `Side24.lean` and `REGISTER.json` byte-identical to the PASS_SCOPED head `215726a2`); #445 integrates first. Scientific effect NONE.",
    "**Ready for review since 2026-10-13 05:20Z, marked so by the integrator, not by the author. Base `main` since #445 merged as `6b5b9a5d` (05:15Z). Head `f6ba2e6a` is the integrator's source-identical carry ([6138841413](https://github.com/d6g8k5htny-coder/Math-/pull/447#issuecomment-6138841413)): parents `06f03d06` (the reviewed head) and landed main `6b5b9a5d`, tree `d2f5bd70` = the reviewed head's tree = `git merge-tree --write-tree 06f03d06 6b5b9a5d`, read back locally by the author from the fetched ref; no source byte changed, so the two reads on `06f03d06` keep their scope. Formerly stacked on #445 (base head `0c506fea` after #445's amendments 445-A to 445-D, merged into this PR as `06f03d06` with the documents regenerated by the same binder; `Side24.lean` and `REGISTER.json` byte-identical to the PASS_SCOPED head `215726a2`). Scientific effect NONE.")
rep("- Hosted runs on the current head `06f03d06` (merge of the amended #445 head `0c506fea`; docs regenerated; module and register byte-identical to `215726a2`), bound 2026-10-13 04:52Z:",
    f"- Hosted runs on the current head `f6ba2e6a` (the integrator's carry; tree `d2f5bd70` identical to `06f03d06`'s; base `main`), bound 2026-10-13 {BOUND}: {line}\n"
    "- Hosted runs on the previous head `06f03d06` (merge of the amended #445 head `0c506fea`; docs regenerated; module and register byte-identical to `215726a2`), bound 2026-10-13 04:52Z:")
rep("Draft; I never mark ready or merge. Needs a nonauthor reader (final byte review of the appended block and the three rows against the design packet) and a distinct integrator after #445. Any amendment to #445 means this stacked candidate is rebuilt from its new head as a new commit.",
    "The author never marks ready or merges. Reads on the source bytes, both at zero independence credit: dot PASS_SCOPED ([6138083647](https://github.com/d6g8k5htny-coder/Math-/pull/447#issuecomment-6138083647)) and PASS_SCOPED_COMPOSITION ([6138686063](https://github.com/d6g8k5htny-coder/Math-/pull/447#issuecomment-6138686063)); the carry changes no source byte. The integrator (Codex, activated on main#307 [6138720490](https://github.com/d6g8k5htny-coder/main/issues/307#issuecomment-6138720490)) carried the branch onto landed main, marked the PR ready at 05:20Z and performs the protected merge; the readiness-triggered Codex review on `f6ba2e6a` completed 05:22:48Z with no review, no review comment and a thumbs-up reaction. #445 is merged; the author pushes nothing further unless asked.")
body = body.rstrip('\n') + '\n'
assert '<<' not in body and body.count('🤖 Generated with [Claude Code]') == 1
Path(S / 'lvs/r7/pr447_body_carry.md').write_text(body)
if '--dry' in sys.argv: print('DRY', len(body)); sys.exit(0)
api('-X', 'PATCH', f'repos/{REPO}/pulls/{PR}', '--input', '-', inp=json.dumps({'body': body}))
after = json.loads(api(f'repos/{REPO}/pulls/{PR}'))['body']
assert FOOT.sub('', after) == body.rstrip('\n'), 'posted body differs beyond the proxy footer'
print('PATCHED', len(body), 'footers after PATCH:', len(FOOT.findall(after)))
